/**
 * Signal Sweep — the rules of the arcade run, kept free of React and the DOM.
 *
 * The component above this file owns timing, sound and storage. Everything in
 * here is a pure transformation of one game state into the next, which keeps
 * the board reproducible in tests and means a paused tab cannot mutate a run.
 */

export const GRID = 20;

export type Point = { x: number; y: number };
export type Direction = "up" | "right" | "down" | "left";
export type GameMode = "classic" | "maze" | "sprint";
export type PowerUpType = "surge" | "shield" | "slow";
export type RunStatus = "playing" | "over" | "won";

export type PowerUp = { type: PowerUpType; point: Point };

export type Effects = {
  /** Moves remaining on the ×2 scoring surge. */
  surgeMoves: number;
  /** Charges that absorb one collision each. */
  shieldCharges: number;
  /** Moves remaining on the stabiliser (slower ticks). */
  slowMoves: number;
};

export type GameState = {
  mode: GameMode;
  snake: Point[];
  direction: Direction;
  food: Point | null;
  obstacles: Point[];
  powerUp: PowerUp | null;
  score: number;
  packets: number;
  combo: number;
  bestCombo: number;
  moves: number;
  movesSincePacket: number;
  level: number;
  timeLeftMs: number | null;
  effects: Effects;
  status: RunStatus;
};

export type GameEvent =
  | { type: "eat"; points: number; combo: number }
  | { type: "powerup"; power: PowerUpType }
  | { type: "shield" }
  | { type: "levelup"; level: number }
  | { type: "crash" }
  | { type: "timeout" }
  | { type: "win" };

export type StepOptions = {
  rng?: () => number;
  /** Time consumed by this tick. Defaults to the state's own speed. */
  elapsedMs?: number;
};

export type StepResult = {
  state: GameState;
  events: GameEvent[];
  /** The delay before the next tick. */
  speed: number;
};

export const MODE_CONFIG = {
  classic: {
    label: "Classic",
    tag: "Endless",
    description: "No clock. Grow the route and keep the loop alive.",
    timeLimitMs: null,
    packetBonusMs: 0,
    basePoints: 10,
    obstacles: false,
  },
  maze: {
    label: "Relay",
    tag: "Maze",
    description: "Fixed walls cut the field. Plan the line before the speed climbs.",
    timeLimitMs: null,
    packetBonusMs: 0,
    basePoints: 12,
    obstacles: true,
  },
  sprint: {
    label: "Sprint",
    tag: "70 sec",
    description: "A shrinking signal window. Every packet buys four more seconds.",
    timeLimitMs: 70_000,
    packetBonusMs: 4_000,
    basePoints: 12,
    obstacles: false,
  },
} as const satisfies Record<
  GameMode,
  {
    label: string;
    tag: string;
    description: string;
    timeLimitMs: number | null;
    packetBonusMs: number;
    basePoints: number;
    obstacles: boolean;
  }
>;

export const COMBO_WINDOW = 18;
export const SURGE_MOVES = 50;
export const SLOW_MOVES = 34;
export const MAX_SHIELD_CHARGES = 2;
export const MAX_COMBO = 5;

export const START_SNAKE: readonly Point[] = [
  { x: 9, y: 10 },
  { x: 8, y: 10 },
  { x: 7, y: 10 },
];

export const VECTORS: Record<Direction, Point> = {
  up: { x: 0, y: -1 },
  right: { x: 1, y: 0 },
  down: { x: 0, y: 1 },
  left: { x: -1, y: 0 },
};

export const OPPOSITE: Record<Direction, Direction> = {
  up: "down",
  right: "left",
  down: "up",
  left: "right",
};

const key = (point: Point) => `${point.x},${point.y}`;

/** A fixed, mirrored obstacle field: enough structure to read, never a trap. */
export function mazeObstacles(): Point[] {
  const points: Point[] = [];
  for (const x of [5, 15]) {
    for (let y = 2; y <= 17; y += 1) {
      if (y < 8 || y > 12) points.push({ x, y });
    }
  }
  for (const y of [5, 15]) {
    for (let x = 8; x <= 12; x += 1) points.push({ x, y });
  }
  for (const [x, y] of [
    [10, 2],
    [10, 3],
    [10, 16],
    [10, 17],
  ]) {
    points.push({ x: x!, y: y! });
  }
  return points;
}

function occupied(state: GameState, extra?: Point | null): Set<string> {
  const cells = new Set(state.snake.map(key));
  for (const point of state.obstacles) cells.add(key(point));
  if (state.food) cells.add(key(state.food));
  if (extra) cells.add(key(extra));
  return cells;
}

/** Every cell a fresh packet or modifier may land on. */
export function freeCells(state: GameState): Point[] {
  const blocked = occupied(state);
  const cells: Point[] = [];
  for (let y = 0; y < GRID; y += 1) {
    for (let x = 0; x < GRID; x += 1) {
      const point = { x, y };
      if (!blocked.has(key(point))) cells.push(point);
    }
  }
  return cells;
}

export function placeFood(state: GameState, rng: () => number = Math.random): Point | null {
  const cells = freeCells(state);
  if (cells.length === 0) return null;
  return cells[Math.min(cells.length - 1, Math.floor(rng() * cells.length))]!;
}

export function placePowerUp(
  state: GameState,
  rng: () => number = Math.random,
): PowerUp | null {
  const cells = freeCells(state);
  if (cells.length === 0) return null;
  const point = cells[Math.min(cells.length - 1, Math.floor(rng() * cells.length))]!;
  const roll = rng();
  // A shield is the rarest modifier; it can only stack two deep.
  const type: PowerUpType =
    state.effects.shieldCharges >= MAX_SHIELD_CHARGES || roll > 0.72
      ? roll > 0.86
        ? "slow"
        : "surge"
      : roll > 0.4
        ? "surge"
        : "shield";
  return { type, point };
}

export function createGame(
  mode: GameMode,
  rng: () => number = Math.random,
): GameState {
  const config = MODE_CONFIG[mode];
  const base: GameState = {
    mode,
    snake: START_SNAKE.map((point) => ({ ...point })),
    direction: "right",
    food: null,
    obstacles: config.obstacles ? mazeObstacles() : [],
    powerUp: null,
    score: 0,
    packets: 0,
    combo: 0,
    bestCombo: 0,
    moves: 0,
    movesSincePacket: 0,
    level: 1,
    timeLeftMs: config.timeLimitMs,
    effects: { surgeMoves: 0, shieldCharges: 0, slowMoves: 0 },
    status: "playing",
  };
  return { ...base, food: placeFood(base, rng) };
}

/** The one place a run's pace is decided. */
export function speedFor(state: GameState): number {
  const base = state.mode === "sprint" ? 132 : 156;
  const levelStep = Math.min(72, Math.max(0, state.level - 1) * 8);
  const mazePenalty = state.mode === "maze" ? 6 : 0;
  let speed = Math.max(72, base - levelStep - mazePenalty);
  if (state.effects.slowMoves > 0) speed = Math.round(speed * 1.5);
  return speed;
}

export function scoreMultiplier(state: GameState): number {
  return Math.max(1, state.combo) * (state.effects.surgeMoves > 0 ? 2 : 1);
}

function applyPowerUp(state: GameState, type: PowerUpType): Effects {
  const effects = { ...state.effects };
  if (type === "surge") effects.surgeMoves = Math.max(effects.surgeMoves, SURGE_MOVES);
  if (type === "slow") effects.slowMoves = Math.max(effects.slowMoves, SLOW_MOVES);
  if (type === "shield") {
    effects.shieldCharges = Math.min(MAX_SHIELD_CHARGES, effects.shieldCharges + 1);
  }
  return effects;
}

/**
 * Advance one tick.
 *
 * A collision that a shield can absorb does not move the head: the charge is
 * spent, the combo resets and the player gets the next tick to steer away.
 */
export function stepGame(
  state: GameState,
  requested: Direction,
  options: StepOptions = {},
): StepResult {
  const rng = options.rng ?? Math.random;
  const events: GameEvent[] = [];
  if (state.status !== "playing") {
    return { state, events, speed: speedFor(state) };
  }

  const elapsed = options.elapsedMs ?? speedFor(state);
  const next: GameState = {
    ...state,
    snake: state.snake.map((point) => ({ ...point })),
    obstacles: state.obstacles.map((point) => ({ ...point })),
    effects: { ...state.effects },
  };

  if (next.timeLeftMs !== null) {
    next.timeLeftMs = Math.max(0, next.timeLeftMs - elapsed);
    if (next.timeLeftMs <= 0) {
      next.status = "over";
      events.push({ type: "timeout" });
      return { state: next, events, speed: speedFor(next) };
    }
  }

  const direction = OPPOSITE[requested] === state.direction ? state.direction : requested;
  next.direction = direction;
  const vector = VECTORS[direction];
  const head = {
    x: next.snake[0]!.x + vector.x,
    y: next.snake[0]!.y + vector.y,
  };
  const eating =
    next.food !== null && next.food.x === head.x && next.food.y === head.y;
  const tail = next.snake.slice(0, -1);
  const body = eating ? next.snake : tail;
  const obstacleCells = new Set(next.obstacles.map(key));
  const crashed =
    head.x < 0 ||
    head.x >= GRID ||
    head.y < 0 ||
    head.y >= GRID ||
    obstacleCells.has(key(head)) ||
    body.some((part) => part.x === head.x && part.y === head.y);

  if (crashed) {
    if (next.effects.shieldCharges > 0) {
      next.effects.shieldCharges -= 1;
      next.combo = 0;
      events.push({ type: "shield" });
      return { state: next, events, speed: speedFor(next) };
    }
    next.status = "over";
    events.push({ type: "crash" });
    return { state: next, events, speed: speedFor(next) };
  }

  next.snake = [head, ...(eating ? next.snake : tail)];
  next.moves += 1;

  if (next.effects.surgeMoves > 0) next.effects.surgeMoves -= 1;
  if (next.effects.slowMoves > 0) next.effects.slowMoves -= 1;

  if (!eating) {
    next.movesSincePacket += 1;
    if (next.movesSincePacket > COMBO_WINDOW) next.combo = 0;
  }

  if (eating) {
    const combo =
      state.movesSincePacket <= COMBO_WINDOW ? Math.min(MAX_COMBO, state.combo + 1) : 1;
    const multiplier = Math.max(1, combo) * (state.effects.surgeMoves > 0 ? 2 : 1);
    const points = MODE_CONFIG[state.mode].basePoints * multiplier;
    next.combo = combo;
    next.bestCombo = Math.max(next.bestCombo, combo);
    next.movesSincePacket = 0;
    next.score += points;
    next.packets += 1;
    const nextLevel = 1 + Math.floor(next.packets / 5);
    if (nextLevel > next.level) {
      next.level = nextLevel;
      events.push({ type: "levelup", level: nextLevel });
    }
    if (next.timeLeftMs !== null) {
      next.timeLeftMs = Math.min(
        MODE_CONFIG.sprint.timeLimitMs + 30_000,
        next.timeLeftMs + MODE_CONFIG.sprint.packetBonusMs,
      );
    }
    next.food = placeFood(next, rng);
    if (next.packets % 4 === 0 && !next.powerUp) {
      next.powerUp = placePowerUp(next, rng);
    }
    events.push({ type: "eat", points, combo });
    if (!next.food) {
      next.status = "won";
      events.push({ type: "win" });
    }
  }

  if (
    next.powerUp &&
    next.powerUp.point.x === head.x &&
    next.powerUp.point.y === head.y
  ) {
    const power = next.powerUp.type;
    next.effects = applyPowerUp(next, power);
    next.powerUp = null;
    events.push({ type: "powerup", power });
  }

  return { state: next, events, speed: speedFor(next) };
}

/** A stable first frame for server render and tests. */
export function readyGame(mode: GameMode): GameState {
  return createGame(mode, () => 0.42);
}

/**
 * Signal Sweep's local record book.
 *
 * Everything here stays on the device. Storage is treated as hostile: a
 * malformed value falls back to a clean book instead of breaking the page.
 */

import type { GameMode } from "./signal-sweep.ts";

export const RECORDS_KEY = "vantage-signal-sweep-v2";
export const LEGACY_BEST_KEY = "vantage-signal-sweep-best";

export type RunRecord = {
  mode: GameMode;
  score: number;
  packets: number;
  combo: number;
  at: number;
};

export type SavedGameRecords = {
  version: 2;
  best: Record<GameMode, number>;
  topRuns: RunRecord[];
  totals: { runs: number; packets: number };
  sound: boolean;
};

const MODES: GameMode[] = ["classic", "maze", "sprint"];
const MAX_RUNS = 6;

export function emptyRecords(): SavedGameRecords {
  return {
    version: 2,
    best: { classic: 0, maze: 0, sprint: 0 },
    topRuns: [],
    totals: { runs: 0, packets: 0 },
    sound: true,
  };
}

function isMode(value: unknown): value is GameMode {
  return typeof value === "string" && MODES.includes(value as GameMode);
}

function nonNegative(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) && value > 0 ? value : 0;
}

function normaliseRun(value: unknown): RunRecord | null {
  if (!value || typeof value !== "object") return null;
  const run = value as Partial<RunRecord>;
  if (!isMode(run.mode)) return null;
  const score = nonNegative(run.score);
  if (score === 0) return null;
  return {
    mode: run.mode,
    score,
    packets: Math.floor(nonNegative(run.packets)),
    combo: Math.max(1, Math.floor(nonNegative(run.combo))),
    at: nonNegative(run.at) || 0,
  };
}

/** Accept only the known shape; ignore fields an older/newer tab added. */
export function normaliseRecords(value: unknown): SavedGameRecords {
  const clean = emptyRecords();
  if (!value || typeof value !== "object") return clean;
  const raw = value as Partial<SavedGameRecords>;
  if (raw.best && typeof raw.best === "object") {
    for (const mode of MODES) {
      clean.best[mode] = Math.floor(nonNegative((raw.best as Record<string, unknown>)[mode]));
    }
  }
  if (Array.isArray(raw.topRuns)) {
    clean.topRuns = raw.topRuns
      .map(normaliseRun)
      .filter((run): run is RunRecord => run !== null)
      .sort(sortRuns)
      .slice(0, MAX_RUNS);
  }
  if (raw.totals && typeof raw.totals === "object") {
    clean.totals.runs = Math.floor(nonNegative(raw.totals.runs));
    clean.totals.packets = Math.floor(nonNegative(raw.totals.packets));
  }
  if (typeof raw.sound === "boolean") clean.sound = raw.sound;
  return clean;
}

function sortRuns(a: RunRecord, b: RunRecord): number {
  return b.score - a.score || b.at - a.at;
}

/** Return a new book with one finished run folded in. */
export function applyRun(records: SavedGameRecords, run: RunRecord): SavedGameRecords {
  const topRuns = [...records.topRuns, run]
    .filter((item) => item.score > 0)
    .sort(sortRuns)
    .slice(0, MAX_RUNS);
  return {
    ...records,
    best: {
      ...records.best,
      [run.mode]: Math.max(records.best[run.mode], run.score),
    },
    topRuns,
    totals: {
      runs: records.totals.runs + 1,
      packets: records.totals.packets + Math.max(0, run.packets),
    },
  };
}

export function applySound(records: SavedGameRecords, sound: boolean): SavedGameRecords {
  return { ...records, sound };
}

/** Read the local book. Safe on the server and under storage restrictions. */
export function readRecords(): SavedGameRecords {
  if (typeof window === "undefined") return emptyRecords();
  let records = emptyRecords();
  try {
    const raw = window.localStorage.getItem(RECORDS_KEY);
    if (raw) records = normaliseRecords(JSON.parse(raw) as unknown);
  } catch {
    records = emptyRecords();
  }
  // Carry a pre-v2 high score forward so an earlier visit is not erased.
  try {
    const legacy = Number(window.localStorage.getItem(LEGACY_BEST_KEY));
    if (Number.isFinite(legacy) && legacy > records.best.classic) {
      records = { ...records, best: { ...records.best, classic: Math.floor(legacy) } };
    }
  } catch {
    // Storage is optional; the run still works without it.
  }
  return records;
}

export function writeRecords(records: SavedGameRecords): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(RECORDS_KEY, JSON.stringify(records));
  } catch {
    // Private browsing or a full quota must not end the game.
  }
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import {
  COMBO_WINDOW,
  GRID,
  MAX_SHIELD_CHARGES,
  MODE_CONFIG,
  SLOW_MOVES,
  SURGE_MOVES,
  createGame,
  freeCells,
  mazeObstacles,
  placeFood,
  readyGame,
  scoreMultiplier,
  speedFor,
  stepGame,
  type GameState,
} from "./signal-sweep.ts";

const rng = () => 0.5;

const pointKey = (point: { x: number; y: number }) => `${point.x},${point.y}`;

function fresh(mode: "classic" | "maze" | "sprint" = "classic"): GameState {
  return createGame(mode, rng);
}

describe("Signal Sweep rules", () => {
  it("starts a clean run on the board without placing a packet under the snake", () => {
    for (const mode of ["classic", "maze", "sprint"] as const) {
      const state = createGame(mode, rng);
      assert.equal(state.status, "playing");
      assert.equal(state.snake.length, 3);
      assert.ok(state.food);
      assert.equal(state.snake.some((part) => pointKey(part) === pointKey(state.food!)), false);
      assert.equal(state.obstacles.length, MODE_CONFIG[mode].obstacles ? mazeObstacles().length : 0);
      assert.equal(state.timeLeftMs, MODE_CONFIG[mode].timeLimitMs);
    }
  });

  it("moves one cell in the requested direction and rejects a direct reversal", () => {
    const state = fresh();
    const forward = stepGame(state, "right", { rng }).state;
    assert.deepEqual(forward.snake[0], { x: 10, y: 10 });

    const reversed = stepGame(forward, "left", { rng }).state;
    assert.deepEqual(reversed.snake[0], { x: 11, y: 10 });
    assert.equal(reversed.status, "playing");
  });

  it("ends the run at a wall and reports the crash once", () => {
    const state: GameState = {
      ...fresh(),
      snake: [{ x: 0, y: 10 }, { x: 1, y: 10 }],
      direction: "left",
      food: { x: 10, y: 10 },
    };
    const result = stepGame(state, "left", { rng });
    assert.equal(result.state.status, "over");
    assert.deepEqual(result.events, [{ type: "crash" }]);
    assert.equal(result.state.score, 0);
  });

  it("spends a shield instead of ending the run, then allows a turn", () => {
    const state: GameState = {
      ...fresh(),
      snake: [{ x: 0, y: 10 }, { x: 1, y: 10 }],
      direction: "left",
      effects: { surgeMoves: 0, shieldCharges: 1, slowMoves: 0 },
    };
    const result = stepGame(state, "left", { rng });
    assert.equal(result.state.status, "playing");
    assert.equal(result.state.effects.shieldCharges, 0);
    assert.equal(result.state.snake[0]!.x, 0);
    assert.deepEqual(result.events, [{ type: "shield" }]);

    const saved = stepGame(result.state, "up", { rng }).state;
    assert.equal(saved.status, "playing");
    assert.equal(saved.snake[0]!.y, 9);
  });

  it("grows, scores, and raises the combo when a packet is eaten", () => {
    const state: GameState = { ...fresh(), food: { x: 10, y: 10 } };
    const result = stepGame(state, "right", { rng });
    assert.equal(result.state.snake.length, 4);
    assert.equal(result.state.packets, 1);
    assert.equal(result.state.score, MODE_CONFIG.classic.basePoints);
    assert.equal(result.state.combo, 1);
    assert.deepEqual(
      result.events.filter((event) => event.type === "eat"),
      [{ type: "eat", points: MODE_CONFIG.classic.basePoints, combo: 1 }],
    );
  });

  it("caps the combo at five and drops it after a quiet window", () => {
    const stacked: GameState = {
      ...fresh(),
      food: { x: 10, y: 10 },
      combo: 4,
      movesSincePacket: 2,
      score: 90,
    };
    const first = stepGame(stacked, "right", { rng }).state;
    assert.equal(first.combo, 5);
    assert.equal(first.score, 90 + MODE_CONFIG.classic.basePoints * 5);

    const quiet: GameState = {
      ...first,
      combo: 5,
      movesSincePacket: COMBO_WINDOW,
      food: { x: 18, y: 2 },
    };
    const afterWindow = stepGame(quiet, "right", { rng }).state;
    assert.equal(afterWindow.combo, 0);
  });

  it("doubles packet value while a surge is active and counts it down", () => {
    const state: GameState = {
      ...fresh(),
      food: { x: 10, y: 10 },
      effects: { surgeMoves: 4, shieldCharges: 0, slowMoves: 0 },
    };
    assert.equal(scoreMultiplier(state), 2);
    const result = stepGame(state, "right", { rng });
    assert.equal(result.state.score, MODE_CONFIG.classic.basePoints * 2);
    assert.equal(result.state.effects.surgeMoves, 3);
  });

  it("applies collected modifiers and clears the pickup", () => {
    const surge: GameState = {
      ...fresh(),
      food: { x: 10, y: 2 },
      powerUp: { type: "surge", point: { x: 10, y: 10 } },
    };
    const surged = stepGame(surge, "right", { rng });
    assert.equal(surged.state.effects.surgeMoves, SURGE_MOVES);
    assert.equal(surged.state.powerUp, null);
    assert.deepEqual(
      surged.events.find((event) => event.type === "powerup"),
      { type: "powerup", power: "surge" },
    );

    const shielded: GameState = {
      ...fresh(),
      food: { x: 10, y: 2 },
      powerUp: { type: "shield", point: { x: 10, y: 10 } },
    };
    assert.equal(
      stepGame(shielded, "right", { rng }).state.effects.shieldCharges,
      1,
    );

    const stabilised: GameState = {
      ...fresh(),
      food: { x: 10, y: 2 },
      powerUp: { type: "slow", point: { x: 10, y: 10 } },
    };
    assert.equal(
      stepGame(stabilised, "right", { rng }).state.effects.slowMoves,
      SLOW_MOVES,
    );
  });

  it("keeps shields capped at two", () => {
    const state: GameState = {
      ...fresh(),
      food: { x: 10, y: 2 },
      effects: { surgeMoves: 0, shieldCharges: MAX_SHIELD_CHARGES, slowMoves: 0 },
      powerUp: { type: "shield", point: { x: 10, y: 10 } },
    };
    assert.equal(
      stepGame(state, "right", { rng }).state.effects.shieldCharges,
      MAX_SHIELD_CHARGES,
    );
  });

  it("blocks the head on a maze wall without moving it", () => {
    const state: GameState = {
      ...createGame("maze", rng),
      snake: [{ x: 4, y: 2 }, { x: 3, y: 2 }],
      direction: "right",
      food: { x: 12, y: 12 },
    };
    const result = stepGame(state, "right", { rng });
    assert.equal(result.state.status, "over");
    assert.equal(result.state.snake[0]!.x, 4);
    assert.ok(state.obstacles.some((part) => part.x === 5 && part.y === 2));
  });

  it("ends a sprint when the clock reaches zero", () => {
    const state: GameState = { ...fresh("sprint"), timeLeftMs: 40 };
    const result = stepGame(state, "right", { rng, elapsedMs: 100 });
    assert.equal(result.state.timeLeftMs, 0);
    assert.equal(result.state.status, "over");
    assert.deepEqual(result.events, [{ type: "timeout" }]);
  });

  it("adds time back for a packet in sprint", () => {
    const state: GameState = {
      ...fresh("sprint"),
      food: { x: 10, y: 10 },
      timeLeftMs: 20_000,
    };
    const result = stepGame(state, "right", { rng, elapsedMs: 100 });
    assert.equal(
      result.state.timeLeftMs,
      20_000 - 100 + MODE_CONFIG.sprint.packetBonusMs,
    );
  });

  it("speeds up with levels and slows down under a stabiliser", () => {
    const base = fresh();
    const higher = { ...base, level: 6 };
    assert.ok(speedFor(higher) < speedFor(base));
    assert.ok(speedFor({ ...base, effects: { ...base.effects, slowMoves: SLOW_MOVES } }) > speedFor(base));
    assert.ok(speedFor({ ...base, level: 99 }) >= 72);
  });

  it("never places food on the snake, wall, or existing packet", () => {
    const state = fresh("maze");
    const occupied = new Set([
      ...state.snake.map(pointKey),
      ...state.obstacles.map(pointKey),
    ]);
    for (let attempt = 0; attempt < 50; attempt += 1) {
      const food = placeFood(state, () => attempt / 50);
      assert.ok(food);
      assert.equal(occupied.has(pointKey(food!)), false);
    }
  });

  it("returns no food when every cell is occupied", () => {
    const cells = [];
    for (let y = 0; y < GRID; y += 1) {
      for (let x = 0; x < GRID; x += 1) cells.push({ x, y });
    }
    const full: GameState = { ...fresh(), snake: cells, food: null };
    assert.equal(placeFood(full, rng), null);
    assert.equal(freeCells(full).length, 0);
  });

  it("declares a win when the final free cell is eaten", () => {
    const cells = [];
    for (let y = 0; y < GRID; y += 1) {
      for (let x = 0; x < GRID; x += 1) cells.push({ x, y });
    }
    // Head sits next to the one remaining cell; the rest of the board is body.
    const snake = cells.filter((point) => pointKey(point) !== "19,19").reverse();
    const headIndex = snake.findIndex((point) => point.x === 18 && point.y === 19);
    const head = snake.splice(headIndex, 1)[0]!;
    const state: GameState = {
      ...fresh(),
      snake: [head, ...snake],
      direction: "right",
      food: { x: 19, y: 19 },
    };
    const result = stepGame(state, "right", { rng });
    assert.equal(result.state.status, "won");
    assert.ok(result.events.some((event) => event.type === "win"));
  });

  it("ignores steps after the run has ended", () => {
    const over: GameState = { ...fresh(), status: "over", score: 30 };
    const result = stepGame(over, "down", { rng });
    assert.equal(result.state, over);
    assert.equal(result.events.length, 0);
    assert.equal(result.state.score, 30);
  });

  it("gives the server a deterministic ready frame", () => {
    assert.deepEqual(readyGame("classic"), readyGame("classic"));
  });
});

