import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ComponentType,
} from "react";
import {
  ArrowDown,
  ArrowLeft,
  ArrowRight,
  ArrowUp,
  Boxes,
  ChevronRight,
  Gauge,
  Grid3x3,
  Pause,
  Play,
  Radio,
  RotateCcw,
  Shield,
  Sparkles,
  Timer,
  Trophy,
  Volume2,
  VolumeX,
  Zap,
} from "lucide-react";

import {
  COMBO_WINDOW,
  MODE_CONFIG,
  OPPOSITE,
  createGame,
  readyGame,
  scoreMultiplier,
  speedFor,
  stepGame,
  type Direction,
  type GameEvent,
  type GameMode,
  type GameState,
  type PowerUpType,
} from "@/lib/game/signal-sweep";
import {
  applyRun,
  applySound,
  emptyRecords,
  readRecords,
  writeRecords,
  type RunRecord,
  type SavedGameRecords,
} from "@/lib/game/signal-sweep-store";

type Phase = "ready" | "running" | "paused" | "over" | "won";
type FeedbackTone = "accent" | "ok" | "warn" | "danger";
type SoundKind = "start" | "eat" | "power" | "shield" | "level" | "over" | "win" | "pause";

type Feedback = { id: number; text: string; tone: FeedbackTone };

type RunSummary = {
  score: number;
  packets: number;
  bestCombo: number;
  moves: number;
  previousBest: number;
  newBest: boolean;
  won: boolean;
  mode: GameMode;
};

const MODE_ORDER: GameMode[] = ["classic", "maze", "sprint"];
const MODE_ICON: Record<GameMode, ComponentType<{ className?: string }>> = {
  classic: Radio,
  maze: Boxes,
  sprint: Timer,
};
const POWER_META: Record<
  PowerUpType,
  { label: string; Icon: ComponentType<{ className?: string }>; cell: string; chip: string }
> = {
  surge: {
    label: "Surge",
    Icon: Zap,
    cell: "bg-[#ffca78] text-[#241505] shadow-[0_0_14px_rgba(255,202,120,0.8)]",
    chip: "border-warn/40 bg-warn/10 text-warn",
  },
  shield: {
    label: "Shield",
    Icon: Shield,
    cell: "bg-[#5fe3ad] text-[#06231a] shadow-[0_0_14px_rgba(95,227,173,0.8)]",
    chip: "border-ok/40 bg-ok/10 text-ok",
  },
  slow: {
    label: "Stabiliser",
    Icon: Gauge,
    cell: "bg-[#c7a6ff] text-[#1a0f2d] shadow-[0_0_14px_rgba(199,166,255,0.7)]",
    chip: "border-[#c7a6ff]/40 bg-[#c7a6ff]/10 text-[#c7a6ff]",
  },
};

const PHASE_LABEL: Record<Phase, string> = {
  ready: "Standby",
  running: "Live run",
  paused: "Paused",
  over: "Run ended",
  won: "Board cleared",
};

const SOUNDS: Record<
  SoundKind,
  { freq: number; at: number; dur: number; type: OscillatorType; gain: number }[]
> = {
  start: [
    { freq: 440, at: 0, dur: 0.08, type: "sine", gain: 0.045 },
    { freq: 660, at: 0.08, dur: 0.1, type: "sine", gain: 0.045 },
  ],
  eat: [
    { freq: 660, at: 0, dur: 0.06, type: "square", gain: 0.028 },
    { freq: 880, at: 0.04, dur: 0.07, type: "square", gain: 0.024 },
  ],
  power: [
    { freq: 520, at: 0, dur: 0.07, type: "triangle", gain: 0.04 },
    { freq: 780, at: 0.07, dur: 0.08, type: "triangle", gain: 0.04 },
    { freq: 1040, at: 0.15, dur: 0.1, type: "triangle", gain: 0.035 },
  ],
  shield: [
    { freq: 260, at: 0, dur: 0.12, type: "sawtooth", gain: 0.03 },
    { freq: 390, at: 0.12, dur: 0.12, type: "sine", gain: 0.03 },
  ],
  level: [
    { freq: 590, at: 0, dur: 0.07, type: "sine", gain: 0.04 },
    { freq: 740, at: 0.07, dur: 0.07, type: "sine", gain: 0.04 },
    { freq: 988, at: 0.14, dur: 0.12, type: "sine", gain: 0.04 },
  ],
  over: [
    { freq: 240, at: 0, dur: 0.18, type: "sawtooth", gain: 0.03 },
    { freq: 160, at: 0.18, dur: 0.28, type: "triangle", gain: 0.035 },
  ],
  win: [
    { freq: 523, at: 0, dur: 0.1, type: "triangle", gain: 0.04 },
    { freq: 659, at: 0.1, dur: 0.1, type: "triangle", gain: 0.04 },
    { freq: 784, at: 0.2, dur: 0.12, type: "triangle", gain: 0.04 },
    { freq: 1047, at: 0.32, dur: 0.22, type: "triangle", gain: 0.04 },
  ],
  pause: [{ freq: 330, at: 0, dur: 0.09, type: "sine", gain: 0.025 }],
};

function formatScore(value: number) {
  return String(value).padStart(3, "0");
}

function formatClock(ms: number | null) {
  if (ms === null) return "—";
  const total = Math.max(0, Math.ceil(ms / 1000));
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`;
}

function eventMessage(events: GameEvent[]): { text: string; tone: FeedbackTone } | null {
  const power = events.find(
    (event): event is Extract<GameEvent, { type: "powerup" }> => event.type === "powerup",
  );
  if (power) return { text: `${POWER_META[power.power].label} online`, tone: "ok" };
  const shield = events.some((event) => event.type === "shield");
  if (shield) return { text: "Shield absorbed the hit", tone: "warn" };
  const level = events.find(
    (event): event is Extract<GameEvent, { type: "levelup" }> => event.type === "levelup",
  );
  if (level) return { text: `Route level ${level.level}`, tone: "ok" };
  const eat = events.find(
    (event): event is Extract<GameEvent, { type: "eat" }> => event.type === "eat",
  );
  if (eat) return { text: `+${eat.points} · ${eat.combo}× chain`, tone: "accent" };
  return null;
}

function eventSound(events: GameEvent[]): SoundKind | null {
  if (events.some((event) => event.type === "crash" || event.type === "timeout")) return "over";
  if (events.some((event) => event.type === "win")) return "win";
  if (events.some((event) => event.type === "powerup")) return "power";
  if (events.some((event) => event.type === "shield")) return "shield";
  if (events.some((event) => event.type === "levelup")) return "level";
  if (events.some((event) => event.type === "eat")) return "eat";
  return null;
}

export function SignalSweepGame() {
  const [mode, setMode] = useState<GameMode>("classic");
  const [game, setGame] = useState<GameState>(() => readyGame("classic"));
  const [phase, setPhase] = useState<Phase>("ready");
  const [records, setRecords] = useState<SavedGameRecords>(emptyRecords);
  const [soundOn, setSoundOn] = useState(true);
  const [feedback, setFeedback] = useState<Feedback | null>(null);
  const [summary, setSummary] = useState<RunSummary | null>(null);
  const [shake, setShake] = useState(false);

  const phaseRef = useRef<Phase>(phase);
  const modeRef = useRef<GameMode>(mode);
  const recordsRef = useRef(records);
  const soundOnRef = useRef(soundOn);
  const directionRef = useRef<Direction>("right");
  const turnQueue = useRef<Direction[]>([]);
  const audioRef = useRef<AudioContext | null>(null);
  const feedbackId = useRef(0);
  const shakeTimer = useRef<number | null>(null);
  const pointerStart = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    phaseRef.current = phase;
  }, [phase]);
  useEffect(() => {
    modeRef.current = mode;
  }, [mode]);
  useEffect(() => {
    recordsRef.current = records;
  }, [records]);
  useEffect(() => {
    soundOnRef.current = soundOn;
  }, [soundOn]);

  useEffect(() => {
    const loaded = readRecords();
    recordsRef.current = loaded;
    setRecords(loaded);
    setSoundOn(loaded.sound);
    soundOnRef.current = loaded.sound;
  }, []);

  useEffect(() => {
    return () => {
      if (shakeTimer.current) window.clearTimeout(shakeTimer.current);
      if (audioRef.current) void audioRef.current.close().catch(() => {});
    };
  }, []);

  const commitRecords = useCallback((next: SavedGameRecords) => {
    recordsRef.current = next;
    setRecords(next);
    writeRecords(next);
  }, []);

  const playSound = useCallback((kind: SoundKind) => {
    if (!soundOnRef.current) return;
    try {
      const AudioCtor =
        window.AudioContext ??
        (window as typeof window & { webkitAudioContext?: typeof AudioContext })
          .webkitAudioContext;
      if (!AudioCtor) return;
      const ctx = audioRef.current ?? new AudioCtor();
      audioRef.current = ctx;
      if (ctx.state === "suspended") void ctx.resume();
      const start = ctx.currentTime;
      for (const tone of SOUNDS[kind]) {
        const oscillator = ctx.createOscillator();
        const gain = ctx.createGain();
        oscillator.type = tone.type;
        oscillator.frequency.value = tone.freq;
        gain.gain.setValueAtTime(0.0001, start + tone.at);
        gain.gain.exponentialRampToValueAtTime(tone.gain, start + tone.at + 0.012);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + tone.at + tone.dur);
        oscillator.connect(gain);
        gain.connect(ctx.destination);
        oscillator.start(start + tone.at);
        oscillator.stop(start + tone.at + tone.dur + 0.03);
      }
    } catch {
      // Audio is a garnish; a blocked context must never break the run.
    }
  }, []);

  const pushFeedback = useCallback((text: string, tone: FeedbackTone) => {
    feedbackId.current += 1;
    setFeedback({ id: feedbackId.current, text, tone });
  }, []);

  useEffect(() => {
    if (!feedback) return;
    const timer = window.setTimeout(() => setFeedback(null), 1700);
    return () => window.clearTimeout(timer);
  }, [feedback]);

  const vibrate = useCallback((pattern: number | number[]) => {
    try {
      if (typeof navigator !== "undefined" && typeof navigator.vibrate === "function") {
        navigator.vibrate(pattern);
      }
    } catch {
      // Haptics are optional.
    }
  }, []);

  const reactToEvents = useCallback(
    (events: GameEvent[]) => {
      const message = eventMessage(events);
      if (message) pushFeedback(message.text, message.tone);
      const sound = eventSound(events);
      if (sound) playSound(sound);
      if (events.some((event) => event.type === "crash")) {
        vibrate([40, 40, 90]);
        setShake(true);
        if (shakeTimer.current) window.clearTimeout(shakeTimer.current);
        shakeTimer.current = window.setTimeout(() => setShake(false), 340);
      } else if (events.some((event) => event.type === "eat")) {
        vibrate(8);
      } else if (events.some((event) => event.type === "powerup")) {
        vibrate([12, 24, 12]);
      }
    },
    [playSound, pushFeedback, vibrate],
  );

  const finishRun = useCallback(
    (finalState: GameState) => {
      const previousBest = recordsRef.current.best[finalState.mode];
      const newBest = finalState.score > previousBest;
      const run: RunRecord = {
        mode: finalState.mode,
        score: finalState.score,
        packets: finalState.packets,
        combo: Math.max(1, finalState.bestCombo),
        at: Date.now(),
      };
      commitRecords(applyRun(recordsRef.current, run));
      setSummary({
        score: finalState.score,
        packets: finalState.packets,
        bestCombo: finalState.bestCombo,
        moves: finalState.moves,
        previousBest,
        newBest,
        won: finalState.status === "won",
        mode: finalState.mode,
      });
      setPhase(finalState.status === "won" ? "won" : "over");
      playSound(finalState.status === "won" ? "win" : "over");
      pushFeedback(
        finalState.status === "won"
          ? "Board cleared"
          : finalState.timeLeftMs === 0
            ? "Signal window closed"
            : "Route lost",
        finalState.status === "won" ? "ok" : "danger",
      );
    },
    [commitRecords, playSound, pushFeedback],
  );

  useEffect(() => {
    if (phase !== "running") return;
    const delay = speedFor(game);
    const timer = window.setTimeout(() => {
      const queued = turnQueue.current.shift();
      if (queued) directionRef.current = queued;
      const result = stepGame(game, directionRef.current, { elapsedMs: delay });
      directionRef.current = result.state.direction;
      setGame(result.state);
      reactToEvents(result.events);
      if (result.state.status !== "playing") finishRun(result.state);
    }, delay);
    return () => window.clearTimeout(timer);
  }, [finishRun, game, phase, reactToEvents]);

  useEffect(() => {
    function onVisibilityChange() {
      if (document.hidden) {
        setPhase((current) => (current === "running" ? "paused" : current));
      }
    }
    document.addEventListener("visibilitychange", onVisibilityChange);
    return () => document.removeEventListener("visibilitychange", onVisibilityChange);
  }, []);

  const beginRun = useCallback(() => {
    const nextMode = modeRef.current;
    directionRef.current = "right";
    turnQueue.current = [];
    setGame(createGame(nextMode));
    setSummary(null);
    setFeedback(null);
    setPhase("running");
    playSound("start");
  }, [playSound]);

  const resume = useCallback(() => {
    setPhase("running");
    playSound("pause");
  }, [playSound]);

  const pause = useCallback(() => {
    setPhase((current) => (current === "running" ? "paused" : current));
    playSound("pause");
  }, [playSound]);

  const steer = useCallback((direction: Direction) => {
    if (phaseRef.current !== "running") return;
    const last = turnQueue.current[turnQueue.current.length - 1] ?? directionRef.current;
    if (direction === last || OPPOSITE[last] === direction) return;
    if (turnQueue.current.length < 2) turnQueue.current.push(direction);
  }, []);

  const chooseMode = useCallback((nextMode: GameMode) => {
    if (phaseRef.current === "running" || phaseRef.current === "paused") return;
    setMode(nextMode);
    modeRef.current = nextMode;
    setGame(readyGame(nextMode));
    setSummary(null);
    setPhase("ready");
  }, []);

  const toggleSound = useCallback(() => {
    const next = !soundOnRef.current;
    soundOnRef.current = next;
    setSoundOn(next);
    commitRecords(applySound(recordsRef.current, next));
    if (next) playSound("pause");
  }, [commitRecords, playSound]);

  const backToBriefing = useCallback(() => {
    setGame(readyGame(modeRef.current));
    setSummary(null);
    setPhase("ready");
  }, []);

  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      const target = event.target as HTMLElement | null;
      const tag = target?.tagName;
      if (
        target?.isContentEditable ||
        tag === "INPUT" ||
        tag === "TEXTAREA" ||
        tag === "SELECT" ||
        tag === "BUTTON" ||
        tag === "A"
      ) {
        return;
      }
      const key = event.key.toLowerCase();
      const directions: Record<string, Direction> = {
        arrowup: "up",
        w: "up",
        arrowright: "right",
        d: "right",
        arrowdown: "down",
        s: "down",
        arrowleft: "left",
        a: "left",
      };
      const direction = directions[key];
      if (direction) {
        event.preventDefault();
        steer(direction);
        return;
      }
      if (key === " ") {
        event.preventDefault();
        if (phaseRef.current === "running") pause();
        else if (phaseRef.current === "paused") resume();
        else beginRun();
      } else if (key === "enter") {
        if (phaseRef.current === "paused") resume();
        else if (phaseRef.current !== "running") beginRun();
      } else if (key === "escape") {
        if (phaseRef.current === "running") pause();
      } else if (key === "r") {
        if (phaseRef.current !== "ready") beginRun();
      } else if (key === "m") {
        toggleSound();
      } else if (key === "1" || key === "2" || key === "3") {
        chooseMode(MODE_ORDER[Number(key) - 1]!);
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [beginRun, chooseMode, pause, resume, steer, toggleSound]);

  const onPointerDown = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (phaseRef.current !== "running") return;
      pointerStart.current = { x: event.clientX, y: event.clientY };
    },
    [],
  );

  const onPointerUp = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      const start = pointerStart.current;
      pointerStart.current = null;
      if (!start || phaseRef.current !== "running") return;
      const dx = event.clientX - start.x;
      const dy = event.clientY - start.y;
      if (Math.max(Math.abs(dx), Math.abs(dy)) < 18) return;
      steer(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? "right" : "left") : dy > 0 ? "down" : "up");
    },
    [steer],
  );

  const modeInfo = MODE_CONFIG[game.mode];
  const best = records.best[game.mode];
  const multiplier = scoreMultiplier(game);
  const nextLevelAt = game.level * 5;
  const levelProgress = Math.min(100, ((game.packets % 5) / 5) * 100);
  const snakeCells = new Map(game.snake.map((part, index) => [`${part.x},${part.y}`, index]));
  const head = game.snake[0]!;
  const headKey = `${head.x},${head.y}`;
  const obstacleCells = new Set(game.obstacles.map((part) => `${part.x},${part.y}`));
  const foodKey = game.food ? `${game.food.x},${game.food.y}` : null;
  const powerKey = game.powerUp ? `${game.powerUp.point.x},${game.powerUp.point.y}` : null;
  const overlay = phase !== "running";
  const overlayMode = MODE_CONFIG[summary?.mode ?? game.mode];
  const topRuns = records.topRuns.slice(0, 4);

  const cells = Array.from({ length: 20 * 20 }, (_, index) => {
    const x = index % 20;
    const y = Math.floor(index / 20);
    const key = `${x},${y}`;
    const snakeIndex = snakeCells.get(key);
    const isHead = key === headKey;
    const isSnake = snakeIndex !== undefined;
    const isFood = key === foodKey;
    const isWall = obstacleCells.has(key);
    const isPower = powerKey === key && game.powerUp;
    const power = isPower ? game.powerUp : null;

    return (
      <div
        key={key}
        className={`relative flex items-center justify-center rounded-[3px] ${
          isHead
            ? "z-10 bg-accent shadow-[0_0_16px_rgba(72,217,255,0.7)]"
            : isSnake
              ? snakeIndex % 2 === 0
                ? "bg-[#1c9dbc] shadow-[0_0_8px_rgba(72,217,255,0.22)]"
                : "bg-[#1789a8]"
              : isFood
                ? "bg-[#ffca78]/[0.06]"
                : isWall
                  ? "bg-[#22384b] shadow-[inset_0_1px_0_rgba(255,255,255,0.08)]"
                  : isPower
                    ? "bg-white/[0.06]"
                    : "bg-white/[0.025]"
        }`}
        aria-hidden="true"
      >
        {isHead ? (
          <ChevronRight
            className="size-[70%] text-[#04111b]"
            style={{
              transform:
                game.direction === "right"
                  ? "rotate(0deg)"
                  : game.direction === "down"
                    ? "rotate(90deg)"
                    : game.direction === "left"
                      ? "rotate(180deg)"
                      : "rotate(-90deg)",
            }}
          />
        ) : null}
        {isFood ? <span className="signal-food-dot size-[52%] rounded-full bg-[#ffca78] shadow-[0_0_14px_rgba(255,202,120,0.9)]" /> : null}
        {power ? (
          <span className={`flex size-[78%] items-center justify-center rounded-full ${POWER_META[power.type].cell}`}>
            {(() => {
              const Icon = POWER_META[power.type].Icon;
              return <Icon className="size-[68%]" />;
            })()}
          </span>
        ) : null}
      </div>
    );
  });

  const activeModifiers = [
    game.effects.surgeMoves > 0
      ? { key: "surge", label: `Surge ×2 · ${game.effects.surgeMoves}`, ...POWER_META.surge }
      : null,
    game.effects.shieldCharges > 0
      ? { key: "shield", label: `Shield · ${game.effects.shieldCharges}`, ...POWER_META.shield }
      : null,
    game.effects.slowMoves > 0
      ? { key: "slow", label: `Stabiliser · ${game.effects.slowMoves}`, ...POWER_META.slow }
      : null,
  ].filter((item): item is NonNullable<typeof item> => item !== null);

  return (
    <section className="mx-auto max-w-6xl py-8 sm:py-12">
      <div className="flex flex-wrap items-end justify-between gap-5 border-b border-border pb-7">
        <div>
          <p className="flex items-center gap-2 font-mono text-[10px] tracking-[0.2em] text-accent uppercase">
            <Radio className="size-3.5" aria-hidden="true" /> Vantage arcade · 01
          </p>
          <h1 className="mt-3 font-serif text-5xl tracking-tight sm:text-6xl">Signal Sweep</h1>
          <p className="mt-3 max-w-xl text-sm leading-relaxed text-muted sm:text-base">
            Route a live signal through a collapsing field. Chain packets, catch modifiers, and
            keep the loop alive across three routes.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <span className="inline-flex items-center gap-2 rounded-full border border-border bg-surface/70 px-3 py-2 text-xs text-subtle">
            <span className="size-2 rounded-full bg-ok shadow-[0_0_10px_rgba(95,227,173,0.7)]" />
            Offline-ready · no account needed
          </span>
          <span className="inline-flex items-center gap-2 rounded-full border border-border bg-surface/70 px-3 py-2 text-xs text-subtle">
            <Trophy className="size-3.5 text-warn" /> {records.totals.runs} local runs
          </span>
        </div>
      </div>

      <div className="mt-7 grid gap-5 lg:grid-cols-[minmax(0,1fr)_20rem]">
        <div className="min-w-0">
          <div className="rounded-t-2xl border border-b-0 border-border bg-surface/70 px-4 py-3 sm:px-5">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div className="flex items-center gap-2 font-mono text-[10px] tracking-[0.15em] text-subtle uppercase">
                <span
                  className={`size-2 rounded-full ${
                    phase === "running"
                      ? "animate-pulse bg-ok"
                      : phase === "paused"
                        ? "bg-warn"
                        : "bg-subtle/50"
                  }`}
                />
                {PHASE_LABEL[phase]} · {modeInfo.label}
              </div>
              <div className="flex items-center gap-2">
                {phase === "running" ? (
                  <button
                    type="button"
                    onClick={pause}
                    className="inline-flex min-h-9 items-center gap-1.5 rounded-lg border border-border px-2.5 text-[11px] font-medium text-muted transition hover:border-accent/50 hover:text-fg"
                  >
                    <Pause className="size-3.5" /> Pause
                  </button>
                ) : (
                  <button
                    type="button"
                    onClick={phase === "paused" ? resume : beginRun}
                    className="inline-flex min-h-9 items-center gap-1.5 rounded-lg border border-border px-2.5 text-[11px] font-medium text-muted transition hover:border-accent/50 hover:text-fg"
                  >
                    <Play className="size-3.5" /> {phase === "paused" ? "Resume" : "Run"}
                  </button>
                )}
                <button
                  type="button"
                  onClick={toggleSound}
                  aria-pressed={soundOn}
                  aria-label={soundOn ? "Mute game sound" : "Enable game sound"}
                  className="inline-flex size-9 items-center justify-center rounded-lg border border-border text-muted transition hover:border-accent/50 hover:text-fg"
                >
                  {soundOn ? <Volume2 className="size-3.5" /> : <VolumeX className="size-3.5" />}
                </button>
              </div>
            </div>

            <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4">
              <HudStat label="Score" value={formatScore(game.score)} accent />
              <HudStat label={`Best · ${modeInfo.tag}`} value={formatScore(best)} />
              <HudStat
                label="Chain"
                value={`${multiplier}×`}
                highlight={multiplier > 1}
                note={game.combo > 1 ? `${game.combo} packet chain` : "collect quickly"}
              />
              {game.timeLeftMs !== null ? (
                <HudStat
                  label="Signal window"
                  value={formatClock(game.timeLeftMs)}
                  warn={game.timeLeftMs <= 15_000}
                  note="+4s per packet"
                />
              ) : (
                <HudStat
                  label="Route level"
                  value={String(game.level).padStart(2, "0")}
                  note={`next at ${nextLevelAt} packets`}
                />
              )}
            </div>
            {game.timeLeftMs === null ? (
              <div className="mt-2 h-1 overflow-hidden rounded-full bg-white/[0.06]">
                <div
                  className="h-full rounded-full bg-accent/70 transition-[width] duration-200"
                  style={{ width: `${levelProgress}%` }}
                />
              </div>
            ) : null}
          </div>

          <div className="rounded-b-2xl border border-border bg-surface/55 p-2.5 shadow-[0_24px_70px_-45px_rgba(72,217,255,0.35)] sm:p-4">
            <div
              className={`signal-board relative mx-auto aspect-square w-full max-w-[620px] touch-none overflow-hidden rounded-xl border border-[#244257] bg-[#061019] p-[2.2%] ${
                shake ? "signal-shake" : ""
              }`}
              onPointerDown={onPointerDown}
              onPointerUp={onPointerUp}
            >
              <div
                role="img"
                aria-label={`Signal board: ${game.snake.length} segments, score ${game.score}, ${game.packets} packets collected${
                  game.food ? `, packet at column ${game.food.x + 1}, row ${game.food.y + 1}` : ""
                }${game.powerUp ? `, ${POWER_META[game.powerUp.type].label} at column ${game.powerUp.point.x + 1}, row ${game.powerUp.point.y + 1}` : ""}`}
                className="grid h-full w-full grid-cols-20 grid-rows-20 gap-[0.55%]"
              >
                {cells}
              </div>
              <div className="signal-scanline pointer-events-none absolute inset-x-0 top-0 h-8 bg-[linear-gradient(180deg,transparent,rgba(72,217,255,0.1),transparent)]" />
              <div className="pointer-events-none absolute inset-0 bg-[linear-gradient(180deg,rgba(255,255,255,0.015),transparent_35%,rgba(0,0,0,0.14))]" />

              {feedback ? (
                <div
                  key={feedback.id}
                  role="status"
                  aria-live="polite"
                  className={`signal-toast pointer-events-none absolute top-4 left-1/2 z-30 -translate-x-1/2 rounded-full border px-3 py-1.5 font-mono text-[10px] tracking-[0.12em] uppercase backdrop-blur-sm ${
                    feedback.tone === "ok"
                      ? "border-ok/40 bg-[#062219]/90 text-ok"
                      : feedback.tone === "warn"
                        ? "border-warn/40 bg-[#241d0d]/90 text-warn"
                        : feedback.tone === "danger"
                          ? "border-danger/40 bg-[#261018]/90 text-danger"
                          : "border-accent/40 bg-[#061a24]/90 text-accent"
                  }`}
                >
                  {feedback.text}
                </div>
              ) : null}

              {overlay ? (
                <div className="absolute inset-0 z-20 flex items-center justify-center bg-[#051019ed] p-4 text-center backdrop-blur-[3px] sm:p-6">
                  {phase === "ready" ? (
                    <div className="max-w-sm">
                      <p className="font-mono text-[9px] tracking-[0.22em] text-accent uppercase">
                        Ready field · {modeInfo.label}
                      </p>
                      <h2 className="mt-3 font-serif text-4xl sm:text-5xl">Route the signal.</h2>
                      <p className="mx-auto mt-3 max-w-xs text-sm leading-relaxed text-muted">
                        {modeInfo.description}
                      </p>
                      <div className="mx-auto mt-4 flex max-w-xs flex-wrap justify-center gap-1.5 font-mono text-[9px] tracking-[0.1em] uppercase">
                        <span className="rounded-full border border-accent/25 bg-accent/[0.06] px-2 py-1 text-accent">
                          +10–60 per packet
                        </span>
                        <span className="rounded-full border border-border bg-white/[0.03] px-2 py-1 text-subtle">
                          chain to 5×
                        </span>
                        <span className="rounded-full border border-border bg-white/[0.03] px-2 py-1 text-subtle">
                          catch modifiers
                        </span>
                      </div>
                      <button
                        type="button"
                        onClick={beginRun}
                        className="mt-6 inline-flex min-h-12 items-center justify-center gap-2 rounded-lg bg-accent px-6 text-sm font-semibold text-accent-fg transition hover:brightness-110"
                      >
                        <Play className="size-4" /> Start {modeInfo.tag.toLowerCase()} run
                      </button>
                      <p className="mt-3 font-mono text-[9px] tracking-[0.14em] text-subtle uppercase">
                        Enter to start · Arrows / WASD to steer
                      </p>
                    </div>
                  ) : null}

                  {phase === "paused" ? (
                    <div className="max-w-sm">
                      <p className="font-mono text-[9px] tracking-[0.22em] text-warn uppercase">
                        Signal held
                      </p>
                      <h2 className="mt-3 font-serif text-4xl sm:text-5xl">Take a breath.</h2>
                      <p className="mx-auto mt-3 max-w-xs text-sm leading-relaxed text-muted">
                        Nothing moves while paused. Your chain is waiting on the board.
                      </p>
                      <button
                        type="button"
                        onClick={resume}
                        className="mt-6 inline-flex min-h-12 items-center justify-center gap-2 rounded-lg bg-accent px-6 text-sm font-semibold text-accent-fg transition hover:brightness-110"
                      >
                        <Play className="size-4" /> Resume run
                      </button>
                      <p className="mt-3 font-mono text-[9px] tracking-[0.14em] text-subtle uppercase">
                        Space or Enter to resume
                      </p>
                    </div>
                  ) : null}

                  {(phase === "over" || phase === "won") && summary ? (
                    <div className="max-w-sm">
                      <p
                        className={`font-mono text-[9px] tracking-[0.22em] uppercase ${
                          phase === "won" ? "text-ok" : "text-danger"
                        }`}
                      >
                        {phase === "won" ? "Perfect route" : "Connection lost"}
                      </p>
                      <h2 className="mt-3 font-serif text-4xl sm:text-5xl">
                        {phase === "won" ? "Board cleared." : "Run complete."}
                      </h2>
                      <p className="mt-3 font-mono text-5xl tabular-nums text-fg">
                        {formatScore(summary.score)}
                      </p>
                      <p className="mt-1 text-xs text-subtle">
                        {summary.packets} packets · {summary.bestCombo || 1}× best chain ·{" "}
                        {summary.moves} moves
                      </p>
                      <p
                        className={`mt-3 text-sm ${
                          summary.newBest ? "font-semibold text-warn" : "text-muted"
                        }`}
                      >
                        {summary.newBest
                          ? `New ${overlayMode.label.toLowerCase()} record — previous best ${formatScore(summary.previousBest)}.`
                          : `Best on this route is still ${formatScore(summary.previousBest)}.`}
                      </p>
                      <div className="mt-5 flex flex-wrap justify-center gap-2">
                        <button
                          type="button"
                          onClick={beginRun}
                          className="inline-flex min-h-11 items-center justify-center gap-2 rounded-lg bg-accent px-5 text-sm font-semibold text-accent-fg transition hover:brightness-110"
                        >
                          <RotateCcw className="size-4" /> Run again
                        </button>
                        <button
                          type="button"
                          onClick={backToBriefing}
                          className="inline-flex min-h-11 items-center justify-center gap-2 rounded-lg border border-border px-4 text-sm font-medium text-muted transition hover:border-accent/50 hover:text-fg"
                        >
                          <Grid3x3 className="size-4" /> Change route
                        </button>
                      </div>
                      <p className="mt-3 font-mono text-[9px] tracking-[0.14em] text-subtle uppercase">
                        Enter to run again · 1 / 2 / 3 to switch route
                      </p>
                    </div>
                  ) : null}
                </div>
              ) : null}
            </div>

            <div className="mt-3 flex flex-wrap items-center justify-between gap-3 px-1">
              <p className="text-xs text-subtle">
                Arrows / WASD steer · Space pause · R restart · Swipe on touch
              </p>
              <div className="flex items-center gap-2">
                {activeModifiers.map((modifier) => (
                  <span
                    key={modifier.key}
                    className={`inline-flex items-center gap-1 rounded-full border px-2 py-1 font-mono text-[9px] uppercase ${modifier.chip}`}
                  >
                    <modifier.Icon className="size-3" /> {modifier.label}
                  </span>
                ))}
                {activeModifiers.length === 0 ? (
                  <span className="font-mono text-[9px] tracking-[0.1em] text-subtle uppercase">
                    No active modifiers
                  </span>
                ) : null}
              </div>
            </div>
          </div>
        </div>

        <aside className="flex min-w-0 flex-col gap-4">
          <div className="rounded-2xl border border-border bg-surface/65 p-4">
            <div className="flex items-center justify-between gap-2">
              <p className="font-mono text-[9px] tracking-[0.18em] text-subtle uppercase">
                Route select
              </p>
              <span className="font-mono text-[9px] text-subtle">1 / 2 / 3</span>
            </div>
            <div className="mt-3 space-y-2">
              {MODE_ORDER.map((id, index) => {
                const info = MODE_CONFIG[id];
                const Icon = MODE_ICON[id];
                const selected = mode === id;
                const locked = phase === "running" || phase === "paused";
                return (
                  <button
                    key={id}
                    type="button"
                    onClick={() => chooseMode(id)}
                    disabled={locked}
                    aria-pressed={selected}
                    className={`group flex w-full items-start gap-3 rounded-xl border px-3 py-2.5 text-left transition disabled:cursor-not-allowed disabled:opacity-55 ${
                      selected
                        ? "border-accent/50 bg-accent/[0.08]"
                        : "border-border bg-white/[0.015] hover:border-accent/30 hover:bg-white/[0.035]"
                    }`}
                  >
                    <span
                      className={`mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-lg ${
                        selected ? "bg-accent text-accent-fg" : "bg-white/[0.06] text-accent/80"
                      }`}
                    >
                      <Icon className="size-4" />
                    </span>
                    <span className="min-w-0">
                      <span className="flex items-baseline gap-2">
                        <span className="text-sm font-semibold text-fg">{info.label}</span>
                        <span className="font-mono text-[8px] tracking-[0.12em] text-subtle uppercase">
                          {info.tag}
                        </span>
                        <span className="ml-auto font-mono text-[9px] text-subtle">
                          {String(index + 1).padStart(2, "0")}
                        </span>
                      </span>
                      <span className="mt-0.5 block text-[11px] leading-snug text-muted">
                        {info.description}
                      </span>
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          <div className="rounded-2xl border border-border bg-surface/65 p-4">
            <p className="font-mono text-[9px] tracking-[0.18em] text-subtle uppercase">
              Run telemetry
            </p>
            <div className="mt-3 grid grid-cols-2 gap-2">
              <Telemetry label="Packets" value={String(game.packets)} />
              <Telemetry label="Best chain" value={`${Math.max(1, game.bestCombo)}×`} />
              <Telemetry label="Level" value={String(game.level).padStart(2, "0")} />
              <Telemetry label="Moves" value={String(game.moves)} />
            </div>
            <div className="mt-3 flex items-start gap-2 rounded-lg border border-accent/15 bg-accent/[0.04] px-2.5 py-2 text-[10px] leading-snug text-subtle">
              <Sparkles className="mt-0.5 size-3 shrink-0 text-accent" />
              <span>
                Chain window: {COMBO_WINDOW} moves. Collect inside it to raise the multiplier, then
                surge for ×2.
              </span>
            </div>
          </div>

          <div className="rounded-2xl border border-border bg-surface/65 p-4">
            <p className="font-mono text-[9px] tracking-[0.18em] text-subtle uppercase">
              Local records
            </p>
            {topRuns.length ? (
              <ol className="mt-3 space-y-2">
                {topRuns.map((run, index) => (
                  <li
                    key={`${run.at}-${index}`}
                    className="grid grid-cols-[1.5rem_1fr_auto] items-baseline gap-2 border-b border-border/60 pb-2 last:border-0 last:pb-0"
                  >
                    <span className="font-mono text-[10px] text-subtle">
                      {String(index + 1).padStart(2, "0")}
                    </span>
                    <span className="min-w-0">
                      <span className="block text-xs font-medium text-fg">
                        {MODE_CONFIG[run.mode].label}
                      </span>
                      <span className="block text-[10px] text-subtle">
                        {run.packets} packets · {run.combo}× chain
                      </span>
                    </span>
                    <span className="font-mono text-sm tabular-nums text-fg">
                      {formatScore(run.score)}
                    </span>
                  </li>
                ))}
              </ol>
            ) : (
              <p className="mt-3 text-xs leading-relaxed text-muted">
                No runs yet. Finish a route and the first line is yours.
              </p>
            )}
          </div>

          <div className="rounded-2xl border border-border bg-surface/65 p-4">
            <p className="font-mono text-[9px] tracking-[0.18em] text-subtle uppercase">
              Steering controls
            </p>
            <div className="mx-auto mt-3 grid w-fit grid-cols-3 gap-2" aria-label="Touch controls">
              <span />
              <ControlButton label="Steer up" direction="up" onPress={steer}>
                <ArrowUp />
              </ControlButton>
              <span />
              <ControlButton label="Steer left" direction="left" onPress={steer}>
                <ArrowLeft />
              </ControlButton>
              <ControlButton label="Steer down" direction="down" onPress={steer}>
                <ArrowDown />
              </ControlButton>
              <ControlButton label="Steer right" direction="right" onPress={steer}>
                <ArrowRight />
              </ControlButton>
            </div>
            <p className="mt-3 text-center text-[11px] text-subtle">
              Tap the arrows or swipe across the board.
            </p>
          </div>

          <div className="flex items-start gap-2.5 rounded-xl border border-accent/15 bg-accent/[0.04] p-3.5 text-[11px] leading-relaxed text-subtle">
            <Shield className="mt-0.5 size-3.5 shrink-0 text-accent" />
            Runs locally in your browser. Records and sound preference stay on this device; no
            account, no upload.
          </div>
        </aside>
      </div>
    </section>
  );
}

function HudStat({
  label,
  value,
  note,
  accent,
  highlight,
  warn,
}: {
  label: string;
  value: string;
  note?: string;
  accent?: boolean;
  highlight?: boolean;
  warn?: boolean;
}) {
  return (
    <div className="rounded-xl border border-border/70 bg-[#07111b]/60 px-3 py-2">
      <p className="truncate font-mono text-[8px] tracking-[0.16em] text-subtle uppercase">
        {label}
      </p>
      <p
        className={`mt-0.5 font-mono text-2xl leading-tight tabular-nums ${
          accent ? "text-fg" : highlight ? "text-warn" : warn ? "text-danger" : "text-muted"
        }`}
      >
        {value}
      </p>
      {note ? <p className="truncate text-[9px] text-subtle">{note}</p> : null}
    </div>
  );
}

function Telemetry({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg border border-border/60 bg-[#07111b]/50 px-2.5 py-2">
      <p className="font-mono text-[8px] tracking-[0.14em] text-subtle uppercase">{label}</p>
      <p className="mt-0.5 font-mono text-lg leading-tight tabular-nums text-fg">{value}</p>
    </div>
  );
}

function ControlButton({
  label,
  direction,
  onPress,
  children,
}: {
  label: string;
  direction: Direction;
  onPress: (direction: Direction) => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      onClick={() => onPress(direction)}
      className="flex size-12 items-center justify-center rounded-xl border border-border bg-raised/60 text-muted transition hover:border-accent/60 hover:bg-accent/10 hover:text-accent active:scale-95"
    >
      {children}
    </button>
  );
}

